NumericalAnalysis/CH7/Lagrange-Interpola.content:
Concept
The basis function defined as
l_j (t_i) = delta_(i j) = cases(1 &amp; comma i = j,
0 &amp; comma i != j)
where t_i is given point then
p_(n - 1) (t) = y_1 l_1 (t) + y_2 l_2 (t) + · · · + y_n l_n (t)
Also we can define l_j as
l_j (t) = product_(i != j)^n (t - t_i)/(t_j - t_i)
Codes
Lagrange interpolation
import numpy as np

def lagrange(t_vals, f_vals, t):
	&quot;&quot;&quot;
		`t_vals`: argument values used to construct the interpolants.
		`f_vals`: function values used to construct the interpolants.
		`t`: Values at which to evaluate the interpolant
	&quot;&quot;&quot;
	m = len(t_vals)
    res = np.empty_like(t)
    for i in range(len(t)):
        res[i] = 0
        for j in range(m):
            sum_up = 1
            sum_down = 1
            for k in range(m):
                if k != j:
                    sum_up *= t[i] - t_vals[k]
                    sum_down *= t_vals[j] - t_vals[k]
            res[i] += sum_up * f_vals[j] / sum_down

    return res

Fast Lagrange interpolation
import numpy as np

def update_w(w, old_m, m):
	for j in range(old_m):
        for k in range(old_m, m):
            if j != k:
                w[j] = w[j] / (t_vals[j] - t_vals[k])
    for j in range(old_m, m):
        w[j] = 1
        for k in range(m):
            if j != k:
                w[j] *= t_vals[j] - t_vals[k]
        w[j] = 1 / w[j]
    return w

def improved_lagrange(t_vals, f_vals, t):
	m = len(t_vals)
    res = np.empty_like(t)

    for i in range(len(t)):
        w = np.empty_like(f_vals)

        w = update_w(w, 0, m)

        right = 1
        for j in range(0, m):
            right *= t[i] - t_vals[j]
        s = 0
        for j in range(m):
            s += f_vals[j] * w[j] / (t[i] - t_vals[j])
        res[i] = right * s
    return res

